CREATE TABLE detached_shell_execution(
 id TEXT PRIMARY KEY NOT NULL, owner_run_id TEXT REFERENCES run(id),
 turn_id TEXT REFERENCES turn(id), schedule_id TEXT REFERENCES schedule(id) ON DELETE CASCADE, detached_thread_id TEXT REFERENCES thread(id) ON DELETE CASCADE, operation_id TEXT NOT NULL UNIQUE,
 state TEXT NOT NULL CHECK(state IN ('starting','running','stopping','exited','failed','stopped')), cwd TEXT NOT NULL, shell_json TEXT NOT NULL CHECK(json_valid(shell_json)),
 input_encoding TEXT NOT NULL, output_encoding TEXT NOT NULL, stdin_state TEXT NOT NULL,
 saved_sequence INTEGER NOT NULL DEFAULT 0 CHECK(saved_sequence>=0), retention_generation INTEGER NOT NULL DEFAULT 0 CHECK(retention_generation>=0),
 exit_code INTEGER, end_reason TEXT, output_complete INTEGER CHECK(output_complete IS NULL OR output_complete IN (0,1)), started_at TEXT NOT NULL, ended_at TEXT,
 CHECK((detached_thread_id IS NULL AND ((schedule_id IS NULL AND owner_run_id IS NOT NULL AND turn_id IS NOT NULL)
    OR (schedule_id IS NOT NULL AND owner_run_id IS NULL AND turn_id IS NULL)))
    OR (detached_thread_id IS NOT NULL AND schedule_id IS NULL AND owner_run_id IS NULL AND turn_id IS NULL AND state IN ('exited','failed','stopped'))));
INSERT INTO detached_shell_execution(id,owner_run_id,turn_id,schedule_id,operation_id,state,cwd,shell_json,input_encoding,output_encoding,stdin_state,saved_sequence,retention_generation,exit_code,end_reason,output_complete,started_at,ended_at) SELECT id,owner_run_id,turn_id,schedule_id,operation_id,state,cwd,shell_json,input_encoding,output_encoding,stdin_state,saved_sequence,retention_generation,exit_code,end_reason,output_complete,started_at,ended_at FROM shell_execution;
DROP TABLE shell_execution;
ALTER TABLE detached_shell_execution RENAME TO shell_execution;
CREATE INDEX shell_schedule_latest ON shell_execution(schedule_id,started_at DESC,id DESC) WHERE schedule_id IS NOT NULL;
CREATE INDEX shell_active_schedule ON shell_execution(schedule_id,state) WHERE state IN ('starting','running','stopping');
