lower(substr(started_at,-1))='z' THEN 1 ELSE 6 END)))>0 AND substr(started_at,21,length(started_at)-20-(CASE WHEN lower(substr(started_at,-1))='z' THEN 1 ELSE 6 END)) NOT GLOB '*[^0-9]*' ELSE length(started_at)=19+(CASE WHEN lower(substr(started_at,-1))='z' THEN 1 ELSE 6 END) END) THEN (CASE WHEN substr(started_at,20,1)='.' THEN CAST(substr((substr(started_at,21,length(started_at)-20-(CASE WHEN lower(substr(started_at,-1))='z' THEN 1 ELSE 6 END)))||'000000000',1,9) AS INTEGER) ELSE 0 END)+(CASE WHEN substr(started_at,18,2)='60' THEN 1000000000 ELSE 0 END) ELSE 0 END),id);
CREATE INDEX shell_active_owner ON shell_execution(owner_run_id,state)
 WHERE state IN ('starting','running','stopping');
CREATE INDEX shell_terminal_time ON shell_execution(COALESCE(ended_at,started_at))
 WHERE state IN ('exited','failed','stopped');
